    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    init_repo(root);
    commit_file(root, "a.txt", b"seed\n", "feat: seed");
    let base = head(root);
    std::fs::write(root.join("a.txt"), b"staged\n").unwrap();
    git(root, &["add", "a.txt"]);
